import fs from 'node:fs';
const runDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dir=`sources/monitor-${runDate}`;fs.mkdirSync(dir,{recursive:true});
const clean=s=>s.replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/\s+/g,' ').trim();
async function get(url){for(let i=0;i<3;i++){try{const r=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('HTTP '+r.status);const t=await r.text();if(!t.includes('licitatie'))throw Error('Unexpected page');return t}catch(e){if(i===2)throw e}}}
const first=await get('https://anabi.just.ro/licitatiionline/ads?page=1&shortBy=price_high_to_low');
const pages=Math.max(...[...first.matchAll(/ads\?page=(\d+)/g)].map(m=>+m[1]));if(!pages)throw Error('Missing pagination');
let all=[],done=0;async function scan(p){const html=p===1?first:await get(`https://anabi.just.ro/licitatiionline/ads?page=${p}&shortBy=price_high_to_low`);fs.writeFileSync(`${dir}/page-${p}.html`,html);const blocks=html.split('<div class="item-loop col-md-3">').slice(1);if(!blocks.length)throw Error('Empty page '+p);for(const b of blocks){const m=b.match(/class="licitatie-box-title" href="([^"]+)" title="([^"]+)"/);if(!m)throw Error('Unparsed listing '+p);all.push({url:m[1],title:clean(m[2]),id:+m[1].match(/auction\/(\d+)/)[1],price:clean(b.match(/Pret de pornire:<\/b>([^<]+)/)?.[1]||''),date:b.match(/data-expire-date="([^"]+)"/)?.[1],category:clean(b.match(/class="price text-muted"[^>]*>([\s\S]*?)<\/a>/)?.[1]||'')})}done++;if(done%10===0)console.log('Pages',done,'/',pages)}
let next=1;await Promise.all([1,2,3].map(async()=>{while(next<=pages)await scan(next++)}));all=[...new Map(all.map(x=>[x.id,x])).values()];
const base=JSON.parse(fs.readFileSync('sources/listings.json'));const state=fs.existsSync('sources/monitor-state.json')?JSON.parse(fs.readFileSync('sources/monitor-state.json')):null;
const known=[...base,...(state?.listings||[])];const ids=new Set([...known.map(x=>x.id),...(state?.seenIds||[])]),urls=new Set([...known.map(x=>x.url),...(state?.seenUrls||[])]);
const unseen=all.filter(x=>!ids.has(x.id)&&!urls.has(x.url));
for(const x of unseen){const h=await get(x.url);fs.writeFileSync(`${dir}/auction-${x.id}.html`,h);const start=h.indexOf('În temeiul'),end=h.indexOf('Istoricul ofertelor');x.text=clean(h.slice(start>=0?start:h.indexOf('<h1'),end>=0?end:undefined));x.tables=[...h.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].map(m=>[...m[1].matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map(c=>clean(c[1])));x.vins=[...new Set(x.text.match(/\b[A-HJ-NPR-Z0-9]{17}\b/g)||[])];}
fs.writeFileSync(`${dir}/listings.json`,JSON.stringify(all,null,2));fs.writeFileSync(`${dir}/new.json`,JSON.stringify(unseen,null,2));fs.writeFileSync(`${dir}/coverage.json`,JSON.stringify({checkedAt:new Date().toISOString(),pages,total:all.length,baseline:base.length,newCount:unseen.length},null,2));console.log('COVERAGE',pages,all.length,'NEW',unseen.length);console.log(JSON.stringify(unseen,null,2));
